import {uid,clamp,weights,rank,redistribute,switchPoint,sample,validateImport,brief} from './core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={fork:'<path d="M12 21v-8C12 7 5 9 5 3m7 10c0-6 7-4 7-10M2 6l3-3 3 3m8 0 3-3 3 3"/>',board:'<rect x="3" y="4" width="7" height="16" rx="2"/><rect x="14" y="4" width="7" height="7" rx="2"/><rect x="14" y="15" width="7" height="5" rx="2"/>',lab:'<path d="M9 3h6m-5 0v6L4 19a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M7 15h10"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l3 4h6a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3v.1"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
let data,view='board',saved=true,labIndex=0,labPercent=null,saveTimer,toastTimer,undo=null;
try{const raw=JSON.parse(localStorage.getItem('fork.v1'));if(raw?.decisions?.length){const ds=validateImport(raw);ds.forEach((d,i)=>d.id=raw.decisions[i].id);data={version:1,decisions:ds,active:raw.active};}}catch{}
if(!data)data={version:1,decisions:[sample()]};
if(!data.decisions.some(d=>d.id===data.active))data.active=data.decisions[0].id;
const active=()=>data.decisions.find(d=>d.id===data.active);
function persist(){saved=false;updateSaved();try{localStorage.setItem('fork.v1',JSON.stringify(data));saved=true;updateSaved();}catch{toast('Your browser couldn’t save. Export a backup to keep your work.');}}
function updateSaved(){const e=$('#save-status');if(e)e.innerHTML=icon(saved?'check':'copy')+(saved?'Saved on this device':'Saving…');}
function toast(msg,canUndo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`${esc(msg)}${canUndo?'<button data-action="undo">Undo</button>':''}`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
const snapshot=()=>undo=JSON.stringify(data);
function render(){const d=active();$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-action="board">${icon('fork')}<span>fork<span class="brand-dot">.</span></span></a><div class="workspace-label">A SPACE TO THINK</div><button class="new-decision" data-action="new">${icon('plus')}New decision <kbd>N</kbd></button><nav aria-label="Main navigation">${[['board','board','Decision board'],['lab','lab','What-if lab'],['library','folder','Your decisions']].map(([v,i,n])=>`<button data-view="${v}" class="nav-item ${view===v?'active':''}">${icon(i)}${n}${v==='library'?`<span class="count">${data.decisions.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-recent"><span class="eyebrow">ON YOUR MIND</span>${data.decisions.slice(0,5).map(x=>`<button class="recent ${x.id===d.id?'selected':''}" data-open="${x.id}"><span class="little-dot"></span>${esc(x.title)}</button>`).join('')}</div><div class="sidebar-bottom"><div class="sidebar-note"><span>↗</span><p>You don’t need a perfect choice.<br>Just a clearer next move.</p></div><button class="help-button" data-action="help">${icon('help')}How Fork works <kbd>?</kbd></button><div class="private-note">${icon('lock')}Private. Yours. No account.</div></div></aside><main><header class="topbar"><span class="breadcrumb">Your thinking space <span>/</span> ${view==='lab'?'What-if lab':view==='library'?'Your decisions':'Decision board'}</span><span id="save-status" class="save-status"></span></header><div class="main-content">${view==='library'?library():view==='lab'?lab():board()}</div><footer><span>Less overthinking. More possibility.</span><span>Made for the beautifully indecisive. <b>fork.</b></span></footer></main>`;updateSaved();}
function pageHead(kicker,title,subtitle,actions=''){return `<section class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${subtitle}</p></div>${actions}</section>`;}
function board(){const d=active();return `${pageHead('A LITTLE STRUCTURE. A LOT OF CLARITY.','Make your next move<span class="green-period">.</span>','Get the options out of your head. See what really matters.',`<button class="button outline export-button" data-action="export">${icon('download')}Export brief</button>`)}<section class="decision-heading"><div class="decision-title-wrap"><span class="tiny-label">THE QUESTION</span><input class="decision-title" aria-label="Decision question" data-title value="${esc(d.title)}" maxlength="100"><input class="decision-note" aria-label="Decision description" data-note value="${esc(d.note)}" placeholder="What’s behind this decision?" maxlength="300"></div><span class="option-counter">${d.options.length} options <i>·</i> ${d.criteria.length} criteria</span></section><section id="results" class="option-grid" style="--cols:${d.options.length}">${cards(d)}</section><section id="insight" class="insight">${insight(d)}</section><section class="matrix-section"><div class="section-heading"><div><span class="eyebrow">01 / THE INGREDIENTS</span><h2>What matters to you?</h2><p>Set the importance. Rate each option from 0 to 10.</p></div><button class="button subtle" data-action="criterion">${icon('plus')}Add criterion</button></div><div class="matrix-scroll"><table class="matrix"><thead><tr><th scope="col">Your criteria <span class="muted small">${d.criteria.length}/8</span></th><th scope="col" class="importance-col">Importance</th>${d.options.map((o,i)=>`<th scope="col"><div class="column-label"><span class="option-dot color-${i}"></span><input aria-label="Option ${i+1} name" data-option-name="${o.id}" value="${esc(o.name)}" maxlength="60"><button class="icon-button" data-remove-option="${o.id}" aria-label="Remove ${esc(o.name)}" ${d.options.length<=2?'disabled':''}>${icon('close')}</button></div></th>`).join('')}<th class="add-option-col" scope="col"><button class="icon-button" data-action="option" aria-label="Add option" ${d.options.length>=5?'disabled':''}>${icon('plus')}</button></th></tr></thead><tbody>${d.criteria.map((c,ci)=>`<tr><th scope="row"><div class="criterion-name"><input aria-label="Criterion ${ci+1} name" data-criterion-name="${c.id}" value="${esc(c.name)}" maxlength="60"><button class="icon-button remove-criterion" data-remove-criterion="${c.id}" aria-label="Remove ${esc(c.name)}" ${d.criteria.length<=1?'disabled':''}>${icon('close')}</button></div><label class="must-have"><input type="checkbox" data-must="${c.id}" ${c.must?'checked':''}>Must-have <span title="Options must score at least 5/10 here to qualify.">≥ 5</span></label></th><td><div class="weight-control"><input type="range" min="0" max="100" value="${c.weight}" aria-label="${esc(c.name)} importance" data-weight="${c.id}"><span data-weight-label="${c.id}">${Math.round(weights(d.criteria)[ci]*100)}%</span></div></td>${d.options.map((o,i)=>`<td><div class="score-control color-${i}"><input type="number" inputmode="decimal" step="0.5" min="0" max="10" aria-label="${esc(o.name)}: ${esc(c.name)} rating" data-score-option="${o.id}" data-score-criterion="${c.id}" value="${o.scores[c.id]??5}"><span>/10</span><div class="mini-track"><i style="width:${clamp(o.scores[c.id])*10}%"></i></div></div></td>`).join('')}<td></td></tr>`).join('')}</tbody></table></div><div class="matrix-foot"><span>${icon('help')}Rate higher for better. For cost, rate <em>affordability</em>.</span><button data-action="option" ${d.options.length>=5?'disabled':''}>${icon('plus')}Add an option <span>${d.options.length}/5</span></button></div></section><section class="bottom-grid"><div class="lab-teaser"><div class="teaser-symbol">${icon('lab')}</div><div><span class="eyebrow">SECOND-GUESS IT. ON PURPOSE.</span><h3>What could change your mind?</h3><p>Turn one priority up. See if a different option comes out on top.</p></div><button class="round-button" data-view="lab" aria-label="Open what-if lab">${icon('arrow')}</button></div><div class="honest-note"><span class="eyebrow">A NOTE FROM FORK</span><p>A score is a conversation starter.<br><em>Your gut still gets a vote.</em></p><span>Your ratings, your priorities, your call.</span></div></section>`;}
function cards(d,override){const rs=rank(d,override),ws=override||weights(d.criteria),hasLeader=rs[0]?.eligible;return d.options.map((o,i)=>{const r=rs.find(x=>x.id===o.id),leader=hasLeader&&r.id===rs[0].id,tied=leader&&rs[1]?.eligible&&Math.abs(rs[0].score-rs[1].score)<.001;return `<article class="option-card color-${i} ${leader?'leader':''}"><div class="card-top"><span>OPTION ${String(i+1).padStart(2,'0')}</span>${leader?`<span class="leading-badge">${icon('spark')}${tied?'Joint leader':'Leading choice'}</span>`:!r.eligible?'<span class="gate-badge">Must-have unmet</span>':''}</div><h3>${esc(o.name)}</h3><div class="score-number">${r.score.toFixed(1)}<span>/100</span></div><div class="contribution-bar" aria-label="Score contribution by criterion">${d.criteria.map((c,j)=>`<span style="width:${clamp(o.scores[c.id])*ws[j]*10}%;opacity:${1-j*.12}" title="${esc(c.name)}: ${(clamp(o.scores[c.id])*ws[j]*10).toFixed(1)} points"></span>`).join('')}</div><div class="card-bottom"><span>${!r.eligible?'Below 5 on '+r.misses.map(c=>esc(c.name)).join(', '):esc(o.note||'An option worth considering')}</span><span class="card-arrow">↗</span></div></article>`;}).join('');}
function insight(d){const rs=rank(d),a=rs[0],b=rs.find(r=>r.id!==a.id&&r.eligible);if(!a.eligible)return `${icon('help')}<div><b>No option meets every must-have.</b><span>Change a rating, relax a must-have, or add another option.</span></div>`;const tie=b&&Math.abs(a.score-b.score)<.001;return `${icon(tie?'help':'spark')}<div><b>${tie?`${esc(a.name)} and ${esc(b.name)} are tied.`:`${esc(a.name)} has the edge${b?` by ${(a.score-b.score).toFixed(1)} points`:''}.`}</b><span>${tie?'Try the what-if lab to understand the trade-off.':b?'Based on what you value right now. Explore the trade-offs before you decide.':'It’s the only option that meets all your must-haves.'}</span></div><button data-view="lab">Test the choice ${icon('arrow')}</button>`;}
function lab(){const d=active();labIndex=Math.min(labIndex,d.criteria.length-1);const c=d.criteria[labIndex],base=weights(d.criteria);if(labPercent===null)labPercent=Math.round(base[labIndex]*100);return `${pageHead('02 / A CHANGE OF PERSPECTIVE','Give “what if” some space<span class="green-period">.</span>','A good choice should survive a little second-guessing.',`<button class="button outline" data-view="board">Back to the board</button>`)}<div class="lab-layout"><section class="lab-controls"><span class="eyebrow">THE QUESTION</span><h2>${esc(d.title)}</h2><label for="lab-select">What if you cared more about…</label><select id="lab-select">${d.criteria.map((x,i)=>`<option value="${i}" ${i===labIndex?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="lab-dial"><span id="lab-pct">${labPercent}<small>%</small></span><span>of your decision</span></div><input id="lab-slider" type="range" min="0" max="100" value="${labPercent}" aria-label="What-if importance"><div class="range-labels"><span>A little less</span><span>A lot more</span></div><p>Other priorities adjust proportionally. Your saved ratings and weights stay unchanged.</p><button class="button subtle" data-action="lab-reset">Reset to your real priorities</button></section><section class="lab-output"><div class="section-heading"><div><span class="eyebrow">THE ALTERNATE REALITY</span><h2>Does the answer change?</h2></div><span class="sandbox-label">${icon('lab')}Sandbox</span></div><div id="lab-ranking"></div><div class="switch-box" id="switch-box"></div><div class="lab-apply"><p>Like this perspective better?</p><button class="button primary" data-action="apply-weights">Make these my priorities ${icon('arrow')}</button></div></section></div><div class="method-note">${icon('help')}Must-haves still apply. A higher total score can’t override an unmet requirement.</div>`;}
function updateLab(){if(view!=='lab')return;const d=active(),ws=redistribute(d.criteria,labIndex,labPercent),rs=rank(d,ws),base=rank(d),point=switchPoint(d,labIndex);$('#lab-ranking').innerHTML=rs.map((o,i)=>`<div class="ranking-row"><span class="rank-num">0${i+1}</span><div class="ranking-body"><div><b>${esc(o.name)}</b><span>${o.score.toFixed(1)} <small>/100</small></span></div><div class="ranking-track color-${o.index}"><i style="width:${o.score}%"></i></div><small>${!o.eligible?'Must-have unmet':o.id===base[0].id?'Your original leading choice':i===0?'A new leading choice':'Still in the running'}</small></div></div>`).join('');$('#lab-pct').innerHTML=`${labPercent}<small>%</small>`;$('#switch-box').innerHTML=`${icon('spark')}<div><b>${point?'There’s a turning point.':'A resilient leading choice.'}</b><p>${point?`At ${point.percent}% importance for ${esc(d.criteria[labIndex].name.toLowerCase())}, ${esc(point.name)} takes the lead.`:base[0].eligible?'Changing this priority alone doesn’t produce a different leader.': 'No option meets your must-haves yet. Adjust them on the board.'}</p></div>`;}
function library(){return `${pageHead('YOUR COLLECTION OF CROSSROADS','Room for every possibility<span class="green-period">.</span>','All your decisions, kept on this device.',`<button class="button primary" data-action="new">${icon('plus')}New decision</button>`)}<div class="library-grid">${data.decisions.map(d=>{const r=rank(d)[0];return `<article class="library-card"><div><span class="eyebrow">${d.options.length} OPTIONS · ${d.criteria.length} CRITERIA</span><button class="icon-button" data-delete="${d.id}" aria-label="Delete ${esc(d.title)}">${icon('trash')}</button></div><h2>${esc(d.title)}</h2><p>${esc(d.note||'A little clarity, waiting for you.')}</p><div class="library-leader"><span class="little-dot"></span>${r.eligible?esc(r.name)+' is leading':'No eligible option yet'}</div><button class="button subtle" data-open="${d.id}">Open decision ${icon('arrow')}</button></article>`;}).join('')}</div><div class="backup-panel"><div>${icon('lock')}<div><b>Your decisions stay in your browser.</b><p>Download a backup before switching devices or clearing browser data.</p></div></div><button class="button outline" data-action="backup">${icon('download')}Back up</button><button class="button outline" data-action="import">Import backup</button></div>`;}
function refresh(){persist();if(view==='board'){const d=active();$('#results').innerHTML=cards(d);$('#insight').innerHTML=insight(d);const ws=weights(d.criteria);d.criteria.forEach((c,i)=>{const e=document.querySelector(`[data-weight-label="${c.id}"]`);if(e)e.textContent=Math.round(ws[i]*100)+'%';});}}
function full(){persist();render();updateLab();}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openModal(html){$('#modal').innerHTML=`<button class="modal-close icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button>${html}`;$('#modal').showModal();}
function newModal(){openModal(`<span class="eyebrow">A FRESH CROSSROADS</span><h2>What’s on your mind?</h2><p>Start with a question. You can change everything later.</p><form id="new-form"><label for="new-title">Your question</label><input id="new-title" name="title" required maxlength="100" placeholder="e.g. Which side project should I build?" autofocus><label for="new-option-a">Your first two options</label><input id="new-option-a" name="a" required maxlength="60" placeholder="One possibility"><input aria-label="Second option" name="b" required maxlength="60" placeholder="Another possibility"><label for="new-template">Start with a few priorities</label><select id="new-template" name="template"><option value="general">Everyday choice · value, ease, excitement</option><option value="project">Next project · usefulness, joy, effort</option><option value="work">Work opportunity · growth, balance, fit</option><option value="blank">Clean slate · add your own</option></select><button class="button primary" type="submit">Make some room for clarity ${icon('arrow')}</button></form>`);}
document.addEventListener('click',e=>{const t=e.target.closest('button,a[data-action]');if(!t)return;if(t.tagName==='A')e.preventDefault();const d=active(),action=t.dataset.action;if(t.dataset.view){view=t.dataset.view;labPercent=null;render();updateLab();window.scrollTo(0,0);return;}if(t.dataset.open){data.active=t.dataset.open;view='board';full();window.scrollTo(0,0);return;}
  if(t.dataset.removeOption){if(d.options.length<=2)return;snapshot();d.options=d.options.filter(o=>o.id!==t.dataset.removeOption);full();toast('Option removed.',true);return;}
  if(t.dataset.removeCriterion){if(d.criteria.length<=1)return;snapshot();d.criteria=d.criteria.filter(c=>c.id!==t.dataset.removeCriterion);full();toast('Criterion removed.',true);return;}
  if(t.dataset.delete){openModal(`<span class="eyebrow">A LITTLE HOUSEKEEPING</span><h2>Delete this decision?</h2><p>This removes it from this browser. You can undo immediately afterward.</p><button class="button danger" data-confirm-delete="${esc(t.dataset.delete)}">Delete decision</button><button class="button outline" data-action="close">Keep it</button>`);return;}
  if(t.dataset.confirmDelete){snapshot();data.decisions=data.decisions.filter(d=>d.id!==t.dataset.confirmDelete);if(!data.decisions.length)data.decisions=[sample()];if(!active())data.active=data.decisions[0].id;$('#modal').close();full();toast('Decision deleted.',true);return;}
  if(action==='new')newModal();
  if(action==='close')$('#modal').close();
  if(action==='board'){view='board';render();}
  if(action==='undo'&&undo){data=JSON.parse(undo);undo=null;full();toast('Restored.');}
  if(action==='option'&&d.options.length<5){d.options.push({id:uid(),name:`Option ${d.options.length+1}`,note:'A new possibility',scores:Object.fromEntries(d.criteria.map(c=>[c.id,5]))});full();toast('Option added. Give it a name in the comparison table.');}
  if(action==='criterion'&&d.criteria.length<8){const id=uid();d.criteria.push({id,name:'New priority',weight:20,must:false});d.options.forEach(o=>o.scores[id]=5);full();toast('Priority added. Rename it in the comparison table.');}
  if(action==='lab-reset'){labPercent=Math.round(weights(d.criteria)[labIndex]*100);$('#lab-slider').value=labPercent;updateLab();}
  if(action==='apply-weights'){const ws=redistribute(d.criteria,labIndex,labPercent);d.criteria.forEach((c,i)=>c.weight=+(ws[i]*100).toFixed(4));view='board';full();toast('New priorities applied.');}
  if(action==='export')openModal(`<span class="eyebrow">TAKE YOUR THINKING WITH YOU</span><h2>Your decision, distilled.</h2><p>A readable brief with your options, priorities, and ratings. No data is uploaded.</p><div class="export-preview"><b>${esc(d.title)}</b><p>${esc(rank(d)[0].name)} · ${rank(d)[0].score.toFixed(1)}/100</p><span>${d.options.length} options · ${d.criteria.length} criteria</span></div><button class="button primary" data-action="download-brief">${icon('download')}Download brief (.md)</button><button class="button outline" data-action="copy-brief">${icon('copy')}Copy summary</button>`);
  if(action==='download-brief'){download(brief(d),'fork-decision-brief.md','text/markdown');toast('Decision brief downloaded.');}
  if(action==='copy-brief'){navigator.clipboard?.writeText(brief(d)).then(()=>toast('Summary copied.')).catch(()=>toast('Clipboard unavailable. Download the brief instead.'));}
  if(action==='backup'){download(JSON.stringify(data,null,2),'fork-backup.json','application/json');toast('Backup downloaded.');}
  if(action==='import')$('#import-file').click();
  if(action==='help')openModal(`<span class="eyebrow">MEET YOUR NEW THINKING PARTNER</span><h2>A little less “what if”.<br>A little more “let’s go”.</h2><ol class="help-steps"><li><b>Put your options on the table.</b><span>Two to five possibilities. Give each one a name.</span></li><li><b>Decide what matters.</b><span>Add up to eight criteria. Set their relative importance. We normalize the weights for you.</span></li><li><b>Rate honestly.</b><span>Higher is always better. A must-have requires at least 5/10. Scores are weighted averages, out of 100.</span></li><li><b>Challenge the result.</b><span>The what-if lab changes one priority without changing your real decision. Look for a choice that feels robust.</span></li></ol><div class="privacy-box">${icon('lock')}No AI guesses, accounts, analytics, or uploads. Your decisions are stored only in this browser. Back them up from Your decisions.</div><p class="small">Keyboard: <kbd>N</kbd> new decision · <kbd>?</kbd> this guide · <kbd>Esc</kbd> close</p>`);
});
document.addEventListener('input',e=>{const t=e.target,d=active();if(t.matches('[data-title]')){d.title=t.value;persist();}if(t.matches('[data-note]')){d.note=t.value;persist();}if(t.dataset.optionName){d.options.find(o=>o.id===t.dataset.optionName).name=t.value;refresh();}if(t.dataset.criterionName){d.criteria.find(c=>c.id===t.dataset.criterionName).name=t.value;refresh();}if(t.dataset.weight){d.criteria.find(c=>c.id===t.dataset.weight).weight=clamp(t.value,0,100);refresh();}if(t.dataset.scoreOption){d.options.find(o=>o.id===t.dataset.scoreOption).scores[t.dataset.scoreCriterion]=clamp(t.value);const track=t.closest('.score-control').querySelector('i');track.style.width=clamp(t.value)*10+'%';refresh();}if(t.id==='lab-slider'){labPercent=Number(t.value);updateLab();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.must){active().criteria.find(c=>c.id===t.dataset.must).must=t.checked;refresh();}if(t.id==='lab-select'){labIndex=+t.value;labPercent=Math.round(weights(active().criteria)[labIndex]*100);render();updateLab();}if(t.matches('[data-score-option]'))t.value=clamp(t.value);if(t.matches('[data-title],[data-option-name],[data-criterion-name]')&&!t.value.trim()){t.value='Untitled';t.dispatchEvent(new Event('input',{bubbles:true}));}if(t.id==='import-file'&&t.files[0]){const file=t.files[0];if(file.size>500000){toast('Choose a backup smaller than 500 KB.');return;}file.text().then(text=>{const imported=validateImport(JSON.parse(text));if(data.decisions.length+imported.length>50)throw new Error('Keep up to 50 decisions on this device.');data.decisions.push(...imported);if(imported.length)data.active=imported[0].id;view='library';full();toast(`${imported.length} decisions imported.`);}).catch(err=>toast(err.message||'Couldn’t read that backup.')).finally(()=>t.value='');}});
document.addEventListener('submit',e=>{if(e.target.id!=='new-form')return;e.preventDefault();if(data.decisions.length>=50){toast('You have 50 decisions. Back up or remove a few first.');return;}const f=new FormData(e.target);if(![f.get('title'),f.get('a'),f.get('b')].every(v=>String(v).trim()))return;const presets={general:['Personal value','Ease & practicality','Excitement'],project:['Real-world usefulness','Excitement to build','Easy to ship','Learning potential'],work:['Growth potential','Work-life balance','Personal fit','Compensation'],blank:['My main priority']};const cs=presets[f.get('template')].map((name,i)=>({id:uid(),name,weight:i===0?40:30,must:false}));const d={id:uid(),title:String(f.get('title')).trim(),note:'',createdAt:new Date().toISOString(),criteria:cs,options:['a','b'].map(k=>({id:uid(),name:String(f.get(k)).trim(),note:'A possibility worth exploring',scores:Object.fromEntries(cs.map(c=>[c.id,5]))}))};data.decisions.unshift(d);data.active=d.id;view='board';$('#modal').close();full();toast('A fresh decision. Start with what matters.');});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||e.ctrlKey||e.metaKey||e.altKey||$('#modal').open)return;if(e.key.toLowerCase()==='n'){e.preventDefault();newModal();}if(e.key==='?')document.querySelector('[data-action="help"]').click();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();persist();
